var i=`ai-assisted-testing`;var s=117;var n={en:[{id:`T117-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Which description best captures the main purpose of `},{t:`AI-Assisted Testing`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Human-in-the-loop design requires a person to review or approve important AI decisions and actions.`},{id:`B`,text:`Specification-driven development starts with an explicit, testable description of required behavior before implementation.`},{id:`C`,text:`AI can accelerate test-case discovery, fixture creation and failure analysis, but generated tests still need an independent behavioral oracle.`},{id:`D`,text:`Context engineering curates the information, tools and constraints available to an AI model for a task.`}]},{id:`T117-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which implementation approach most directly applies `},{t:`AI-Assisted Testing`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Treat external text as data, enforce instruction hierarchy in the agent runtime, sandbox tools, restrict file/network permissions and protect secrets.`},{id:`B`,text:`Build a representative task set with frozen requirements, hidden or independent tests, budgets and scoring rules.`},{id:`C`,text:`Define permitted tools and data, code review ownership, test gates, third-party license checks, artifact provenance, logging and handling of sensitive source.`},{id:`D`,text:`Derive tests from requirements and threat models, ask AI for edge cases and properties, then inspect assertions and run tests against deliberate mutants.`}]},{id:`T117-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`A team faces this situation: `},{t:`An AI assistant might generate tests for overlapping booking intervals, leap days, cancellations and two users racing for the last room.`,b:!0},{t:` What is the most appropriate response?`}]}],options:[{id:`A`,text:`A hotel cancellation specification defines who may cancel, refund windows, inventory release, notification policy and retry behavior before anyone generates controllers or database models.`},{id:`B`,text:`A malicious README may tell a coding agent to read environment secrets and upload them while 'fixing tests.' Repository content must never authorize secret exfiltration or unrelated shell commands.`},{id:`C`,text:`A coding agent can update unit tests freely in a branch but should require approval before running a migration that changes production booking records.`},{id:`D`,text:`The expected outcomes must be confirmed by the business rules.`}]},{id:`T117-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`When using `},{t:`AI-Assisted Testing`,b:!0},{t:`, which trade-off or common mistake deserves particular attention?`}]}],options:[{id:`A`,text:`An approval prompt is useless if the reviewer lacks context or receives an opaque action summary.`},{id:`B`,text:`Overly bureaucratic governance drives shadow AI usage; overly permissive rules create silent risk.`},{id:`C`,text:`AI often writes tests that assert the current implementation instead of the intended behavior.`},{id:`D`,text:`Overly prescriptive specs constrain harmless design choices; vague ones create plausible but wrong code.`}]},{id:`T117-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Is the following statement accurate?`}]},{k:`quote`,runs:[{t:`The goal is finding faults, not merely increasing test count.`}]}]},{id:`T117-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`True or false?`}]},{k:`quote`,runs:[{t:`An AI-generated test is reliable whenever it matches the current implementation.`}]}]},{id:`T117-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Is this guidance or caution accurate for the concept?`}]},{k:`quote`,runs:[{t:`High coverage with incorrect assertions can create false confidence and lock in bugs.`}]}]},{id:`T117-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` statements that correctly characterize `},{t:`AI-Assisted Testing`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Derive tests from requirements and threat models, ask AI for edge cases and properties, then inspect assertions and run tests against deliberate mutants.`},{id:`B`,text:`More repository context always improves an agent's results, even when it is stale.`},{id:`C`,text:`AI can accelerate test-case discovery, fixture creation and failure analysis, but generated tests still need an independent behavioral oracle.`},{id:`D`,text:`Passing AI-written tests proves their assertions match independent product requirements.`}]},{id:`T117-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` observations consistent with a sound application of `},{t:`AI-Assisted Testing`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`An AI-generated test is reliable whenever it matches the current implementation.`},{id:`B`,text:`The expected outcomes must be confirmed by the business rules.`},{id:`C`,text:`License and provenance checks can be skipped for AI-assisted pull requests.`},{id:`D`,text:`High coverage with incorrect assertions can create false confidence and lock in bugs.`}]},{id:`T117-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`An AI agent works on this task: `},{t:`An AI assistant might generate tests for overlapping booking intervals, leap days, cancellations and two users racing for the last room.`,b:!0},{t:` Which proposed verification task most directly tests the required behavior?`}]}],options:[{id:`A`,text:`Give an agent a cancellation feature brief and ask it first to extract invariants, ambiguities and acceptance tests. Only then permit implementation within declared module boundaries.`},{id:`B`,text:`Ask an agent to derive reservation tests solely from a written policy, then compare them with implementation and flag mismatches instead of adjusting expectations to pass.`},{id:`C`,text:`Ask an agent to classify planned operations by low, medium and high risk, with appropriate approval gates, audit records and rollback plans.`},{id:`D`,text:`Ask an agent to draft a one-page AI coding policy with approved data, tool access, review rules, security controls, audit evidence, exception handling and accountable owners.`}]},{id:`T117-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`How do you prevent generated tests from merely confirming generated code?`}]}]},{id:`T117-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`In this situation — `},{t:`An AI assistant might generate tests for overlapping booking intervals, leap days, cancellations and two users racing for the last room.`,b:!0},{t:` — what two specific signals would make you change the design used for `},{t:`AI-Assisted Testing`,b:!0},{t:`? Explain how you would measure them.`}]}]},{id:`T117-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`For this case — `},{t:`An AI assistant might generate tests for overlapping booking intervals, leap days, cancellations and two users racing for the last room.`,b:!0},{t:` — propose three checks for `},{t:`AI-Assisted Testing`,b:!0},{t:`: one normal case, one failure or boundary case, and one check for changing requirements. Give expected outcomes.`}]}]},{id:`T117-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Design decision: `},{t:`An AI assistant might generate tests for overlapping booking intervals, leap days, cancellations and two users racing for the last room.`,b:!0}]},{k:`p`,runs:[{t:`Describe your chosen approach, an alternative you rejected, the most important trade-off, and two concrete acceptance checks. Keep the proposal feasible for a real project.`}]}]},{id:`T117-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Review an AI-generated change for `},{t:`AI-Assisted Testing`,b:!0},{t:`. The agent says the feature is complete for this situation: `},{t:`An AI assistant might generate tests for overlapping booking intervals, leap days, cancellations and two users racing for the last room.`,b:!0},{t:`. It shows a successful demo, but its PR contains no explicit failure-case analysis or verification plan.`}]},{k:`p`,runs:[{t:`Identify at least `},{t:`two topic-specific risks`,b:!0},{t:`, propose the tests/evidence required before approval, and state whether you would approve, request changes, or block deployment. Explain why.`}]}]}],ua:[{id:`T117-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Яке формулювання найточніше передає призначення `},{t:`Тестування за допомогою ШІ`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`HITL означає, що людина перевіряє або затверджує важливі рішення й дії ШІ.`},{id:`B`,text:`Розробка на основі специфікацій починається з чіткого, перевірюваного опису поведінки до реалізації.`},{id:`C`,text:`ШІ пришвидшує пошук тестових випадків, створення фікстур та аналіз падінь, але згенерованим тестам усе одно потрібен незалежний еталон поведінки.`},{id:`D`,text:`Інженерія контексту керує інформацією, інструментами та обмеженнями, доступними ШІ для задачі.`}]},{id:`T117-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який спосіб реалізації найкраще відповідає `},{t:`Тестування за допомогою ШІ`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Сприймайте зовнішній текст як дані, забезпечуйте ієрархію інструкцій у runtime агента, ізолюйте інструменти, обмежуйте файли/мережу й захищайте секрети.`},{id:`B`,text:`Створіть репрезентативний набір задач зі сталими вимогами, прихованими або незалежними тестами, бюджетами та метриками.`},{id:`C`,text:`Визначте дозволені інструменти й дані, відповідальних за review, тестові gates, перевірки ліцензій, походження артефактів, журнали й роботу з чутливим кодом.`},{id:`D`,text:`Виводьте тести з вимог і моделі загроз, просіть ШІ запропонувати граничні випадки та властивості, перевіряйте assertions і запускайте проти навмисних мутацій.`}]},{id:`T117-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Команда має таку ситуацію: `},{t:`ШІ може створити тести перетину бронювань, високосних дат, скасувань і гонки за останній номер.`,b:!0},{t:` Яке рішення найдоречніше?`}]}],options:[{id:`A`,text:`Специфікація скасування бронювання визначає права, періоди повернення грошей, звільнення номера, сповіщення й повтори до генерації контролерів чи моделей БД.`},{id:`B`,text:`Текст репозиторію не має права дозволяти витік секретів чи сторонні команди.`},{id:`C`,text:`Агент може вільно оновлювати unit-тести в гілці, але має отримати дозвіл перед міграцією production-записів бронювання.`},{id:`D`,text:`Очікуваний результат треба звірити з бізнес-правилами.`}]},{id:`T117-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Який компроміс або типову помилку особливо важливо врахувати під час застосування `},{t:`Тестування за допомогою ШІ`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Запит дозволу марний, якщо рев’юер не розуміє контексту й бачить нечіткий опис.`},{id:`B`,text:`Надмірна бюрократія стимулює приховане використання ШІ, а надто вільні правила створюють непомітний ризик.`},{id:`C`,text:`ШІ часто пише тести під поточну реалізацію, а не під задуману поведінку.`},{id:`D`,text:`Надто детальна специфікація диктує несуттєві рішення, а нечітка породжує правдоподібний, але неправильний код.`}]},{id:`T117-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Чи правильне твердження?`}]},{k:`quote`,runs:[{t:`Мета — знаходити збої, а не множити тести.`}]}]},{id:`T117-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Правда чи неправда?`}]},{k:`quote`,runs:[{t:`Тест від ШІ надійний, якщо збігається з поточною реалізацією.`}]}]},{id:`T117-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Чи коректна ця порада або пересторога для цієї концепції?`}]},{k:`quote`,runs:[{t:`Високе coverage з хибними assertions створює фальшиву впевненість і закріплює баги.`}]}]},{id:`T117-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` твердження, які правильно характеризують `},{t:`Тестування за допомогою ШІ`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Виводьте тести з вимог і моделі загроз, просіть ШІ запропонувати граничні випадки та властивості, перевіряйте assertions і запускайте проти навмисних мутацій.`},{id:`B`,text:`Більше контексту репозиторію завжди покращує відповіді агента, навіть якщо він застарілий.`},{id:`C`,text:`ШІ пришвидшує пошук тестових випадків, створення фікстур та аналіз падінь, але згенерованим тестам усе одно потрібен незалежний еталон поведінки.`},{id:`D`,text:`Успішні тести від ШІ доводять відповідність їхніх перевірок незалежним вимогам.`}]},{id:`T117-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` спостереження, що відповідають правильному застосуванню `},{t:`Тестування за допомогою ШІ`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Тест від ШІ надійний, якщо збігається з поточною реалізацією.`},{id:`B`,text:`Очікуваний результат треба звірити з бізнес-правилами.`},{id:`C`,text:`Перевірки ліцензій і походження можна пропускати для PR за участю ШІ.`},{id:`D`,text:`Високе coverage з хибними assertions створює фальшиву впевненість і закріплює баги.`}]},{id:`T117-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`ШІ-агент працює над завданням: `},{t:`ШІ може створити тести перетину бронювань, високосних дат, скасувань і гонки за останній номер.`,b:!0},{t:` Яка запропонована перевірка найкраще підтверджує потрібну поведінку?`}]}],options:[{id:`A`,text:`Дайте агенту опис скасування і попросіть спершу виписати інваріанти, неоднозначності й приймальні тести. Лише потім дозвольте реалізацію в заданих межах модулів.`},{id:`B`,text:`Попросіть агента вивести тести бронювання лише з письмової політики, потім зіставити їх із реалізацією та позначити розбіжності, а не підлаштовувати очікування.`},{id:`C`,text:`Попросіть агента класифікувати заплановані дії за низьким, середнім і високим ризиком та додати погодження, аудит і план відкату.`},{id:`D`,text:`Попросіть агента скласти односторінкову політику AI-коду: дозволені дані, доступ до інструментів, review, безпека, аудит, винятки й відповідальні.`}]},{id:`T117-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Як не допустити, щоб згенеровані тести просто підтверджували згенерований код?`}]}]},{id:`T117-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У ситуації `},{t:`ШІ може створити тести перетину бронювань, високосних дат, скасувань і гонки за останній номер.`,b:!0},{t:` назвіть два конкретні сигнали, за яких ви змінили б рішення для `},{t:`Тестування за допомогою ШІ`,b:!0},{t:`. Як саме їх виміряти?`}]}]},{id:`T117-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Для випадку `},{t:`ШІ може створити тести перетину бронювань, високосних дат, скасувань і гонки за останній номер.`,b:!0},{t:` запропонуйте три перевірки `},{t:`Тестування за допомогою ШІ`,b:!0},{t:`: типовий сценарій, збій або граничну умову та зміну вимог. Наведіть очікувані результати.`}]}]},{id:`T117-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Архітектурне рішення: `},{t:`ШІ може створити тести перетину бронювань, високосних дат, скасувань і гонки за останній номер.`,b:!0}]},{k:`p`,runs:[{t:`Опишіть обраний підхід, відхилену альтернативу, найважливіший компроміс і дві конкретні перевірки приймання. Рішення має бути практичним.`}]}]},{id:`T117-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Перевірте зміну, згенеровану ШІ, з теми `},{t:`Тестування за допомогою ШІ`,b:!0},{t:`. Агент стверджує, що функція готова для ситуації: `},{t:`ШІ може створити тести перетину бронювань, високосних дат, скасувань і гонки за останній номер.`,b:!0},{t:`. Він показав успішне демо, але PR не містить аналізу збоїв або плану перевірок.`}]},{k:`p`,runs:[{t:`Назвіть щонайменше `},{t:`два ризики, специфічні для теми`,b:!0},{t:`, запропонуйте тести/докази перед погодженням і оберіть: погодити, повернути на доопрацювання чи заблокувати реліз. Обґрунтуйте рішення.`}]}]}]};var r={slug:i,topicId:117,questions:n};export{r as default,n as questions,i as slug,s as topicId};